CREATE TABLE users (name TEXT, age INTEGER);
INSERT INTO users VALUES ('Alice', 30), ('Bob', NULL), ('Charlie', 25);
SELECT COUNT(age) FROM users;

SELECT department, COUNT(*) 
FROM employees 
GROUP BY department;

SELECT region, COUNT(*), SUM(sales) 
FROM transactions 
GROUP BY region;

SELECT gender, AVG(age) 
FROM students 
GROUP BY gender;

SELECT category, MIN(price), MAX(price) 
FROM products 
GROUP BY category;

CREATE TABLE t (val INTEGER);
INSERT INTO t VALUES (1), (2), (NULL), (4);
SELECT SUM(val) FROM t;

SELECT department, MAX(salary) - MIN(salary) as salary_range
FROM employees
GROUP BY department;

SELECT COUNT(DISTINCT customer_id)
FROM orders
WHERE order_date BETWEEN '2024-01-01' AND '2024-12-31';

CREATE TABLE t (val INTEGER);
INSERT INTO t VALUES (2), (4), (NULL), (6);
SELECT AVG(val) FROM t;

SELECT department, role, SUM(salary)
FROM employees
GROUP BY department, role;

SELECT department, employee_name, salary,
RANK() OVER (PARTITION BY department ORDER BY salary DESC) as rank
FROM employees;

SELECT product_id, sale_date, amount,
SUM(amount) OVER (PARTITION BY product_id ORDER BY sale_date) as cumulative_sales
FROM sales;

SELECT salesperson, quarter, revenue,
LAG(revenue, 1) OVER (PARTITION BY salesperson ORDER BY quarter) as prev_quarter_revenue
FROM quarterly_sales;

SELECT name, salary,
NTILE(4) OVER (ORDER BY salary DESC) as quartile
FROM employees;

SELECT *,
FIRST_VALUE(salary) OVER (PARTITION BY department ORDER BY hire_date) as first_hire_salary
FROM employees;

SELECT department, employee, salary,
salary - LAG(salary, 1) OVER (PARTITION BY department ORDER BY salary) as diff_from_prev
FROM employees;

SELECT name, department, salary,
NTILE(3) OVER (PARTITION BY department ORDER BY salary DESC) as tercile
FROM employees;

SELECT current_setting('geqo_threshold') as geqo_limit,
current_setting('geqo_effort') as geqo_effort,
current_setting('from_collapse_limit') as collapse_limit;
